// This file is generated by AI.

//! 预览静音桥: 往被预览的 `index.html` 里注入一段脚本, 用它统一控制所有声道。
//!
//! # 为什么不去改引擎
//!
//! 引擎里"音量"不是一个字段, 而是几条各算各的链路: BGM 由一条**递归淡入**定时器不停写
//! `audio.volume`, 语音、音效、UI 音效各自在创建元素时算一次, Live2D 还有自己的
//! `SoundManager.volume`。想从引擎内部静音, 就得同时按住所有这些写入方 —— 逐个改既
//! 脆弱 (漏一个就"静了音还在响"), 又要求用户必须用改过的引擎。
//!
//! 这里改用**宿主注入**: 在页面最前面挂住 `HTMLMediaElement.prototype.volume`, 把每个
//! 元素"想要的音量"记下来, 实际写下去的是它乘以一个全局输出系数。于是:
//!
//! * 静音 = 把输出系数置 0, 立刻对**所有**已存在的 `audio` / `video` 生效;
//! * 之后新建的元素、引擎自己反复改的音量, 都会经过同一个钩子, 因此不会"静着静着又响了";
//! * 完全不依赖引擎版本 —— 任何 WebGAL 引擎都能用。
//!
//! 与 `[`super::sync`]` 的协议命令无关: 那条路要改引擎, 这条路不用。

use std::sync::atomic::{AtomicBool, Ordering};

/// 注入标记: 已经注入过就不再注入 (幂等)。
const PREVIEW_AUDIO_BRIDGE_MARKER: &str = "webgal-ink-preview-audio-bridge";

/// 宿主 -> 预览页面 的静音设置消息类型 (与编辑器侧 `preview/audio-bridge.ts` 对齐)。
const OUTPUT_SETTINGS_MESSAGE_TYPE: &str = "webgal.preview.output-settings";

pub struct PreviewAudioBridge {
    muted: AtomicBool,
}

impl PreviewAudioBridge {
    pub fn new(muted: bool) -> Self {
        Self {
            muted: AtomicBool::new(muted),
        }
    }

    /// 记录静音状态。返回是否发生了变化。
    ///
    /// 这个值只在**下一次**注入时用到 (作为页面加载时的初始状态) —— 已经打开的页面靠
    /// 宿主发消息实时改, 见编辑器侧的 `previewClient.setMuted`。
    pub fn set_muted(&self, muted: bool) -> bool {
        self.muted.swap(muted, Ordering::SeqCst) != muted
    }

    pub fn muted(&self) -> bool {
        self.muted.load(Ordering::SeqCst)
    }

    /// 把桥注入到 `index.html`; 其它路径或已注入过则原样返回。
    pub fn inject(&self, logical_path: &str, html: &str) -> Option<String> {
        if logical_path != "index.html" || html.contains(PREVIEW_AUDIO_BRIDGE_MARKER) {
            return None;
        }

        let script = self.build_script();
        // 放在 `</head>` 之前, 让它在引擎脚本之前执行 (否则第一批音频已经按原音量播出去了)
        let index = html.find("</head>").unwrap_or(0);
        let mut output = String::with_capacity(html.len() + script.len());
        output.push_str(&html[..index]);
        output.push_str(&script);
        output.push_str(&html[index..]);
        Some(output)
    }

    fn build_script(&self) -> String {
        let muted = if self.muted() { "true" } else { "false" };
        format!(
            r#"<script data-{marker}>
(() => {{
  // 只在 iframe 里生效 (父窗口自己不需要这套)
  if (window.parent === window) return;

  const messageType = '{message_type}';
  const volumeDescriptor = Object.getOwnPropertyDescriptor(HTMLMediaElement.prototype, 'volume');
  const nativePlay = HTMLMediaElement.prototype.play;
  if (!volumeDescriptor || !volumeDescriptor.get || !volumeDescriptor.set || !volumeDescriptor.configurable) return;

  // 每个媒体元素"想要的音量"。引擎写的值记在这里, 真正写进元素的是它乘上输出系数 ——
  // 这样引擎的淡入淡出照常跑, 只是整体被压到 0。
  const requestedVolumes = new WeakMap();
  let outputVolume = {muted} ? 0 : 1;

  const clamp = (value) => Math.min(Math.max(Number(value) || 0, 0), 1);
  const applyVolume = (element) => {{
    const requested = requestedVolumes.has(element)
      ? requestedVolumes.get(element)
      : volumeDescriptor.get.call(element);
    requestedVolumes.set(element, requested);
    volumeDescriptor.set.call(element, clamp(requested * outputVolume));
  }};
  const applyAll = () => document.querySelectorAll('audio, video').forEach(applyVolume);

  Object.defineProperty(HTMLMediaElement.prototype, 'volume', {{
    configurable: true,
    enumerable: volumeDescriptor.enumerable,
    get() {{
      return requestedVolumes.has(this) ? requestedVolumes.get(this) : volumeDescriptor.get.call(this);
    }},
    set(value) {{
      const requested = clamp(value);
      requestedVolumes.set(this, requested);
      volumeDescriptor.set.call(this, requested * outputVolume);
    }},
  }});

  // 补一次: 元素可能在钩子生效前就已经设过音量
  HTMLMediaElement.prototype.play = function (...args) {{
    applyVolume(this);
    return nativePlay.apply(this, args);
  }};

  const parentTargetOrigin = (() => {{
    if (!document.referrer) return '*';
    try {{
      return new URL(document.referrer).origin;
    }} catch {{
      return '*';
    }}
  }})();

  window.addEventListener('message', (event) => {{
    if (event.source !== window.parent) return;
    const data = event.data;
    if (!data || typeof data !== 'object' || data.type !== messageType) return;
    if (typeof data.muted !== 'boolean') return;
    // 一旦收到宿主的明确设置, 就以它为准 (注入时的初始值可能已经过期)
    outputVolume = data.muted ? 0 : 1;
    applyAll();
  }});

  applyAll();
}})();
</script>"#,
            marker = PREVIEW_AUDIO_BRIDGE_MARKER,
            message_type = OUTPUT_SETTINGS_MESSAGE_TYPE,
            muted = muted,
        )
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn injects_before_head_end() {
        let bridge = PreviewAudioBridge::new(false);
        let html = "<html><head><title>t</title></head><body></body></html>";
        let injected = bridge.inject("index.html", html).expect("应当注入");
        assert!(injected.contains(PREVIEW_AUDIO_BRIDGE_MARKER));
        // 必须在 </head> 之前: 引擎脚本要晚于它执行
        let script_index = injected.find(PREVIEW_AUDIO_BRIDGE_MARKER).unwrap();
        let head_end_index = injected.find("</head>").unwrap();
        assert!(script_index < head_end_index);
    }

    #[test]
    fn injection_is_idempotent() {
        let bridge = PreviewAudioBridge::new(false);
        let html = "<html><head></head></html>";
        let once = bridge.inject("index.html", html).unwrap();
        assert!(bridge.inject("index.html", &once).is_none());
    }

    #[test]
    fn only_index_html_is_injected() {
        let bridge = PreviewAudioBridge::new(false);
        assert!(bridge
            .inject("game/scene/start.txt", "<html></html>")
            .is_none());
        assert!(bridge.inject("index.html", "<html></html>").is_some());
    }

    #[test]
    fn muted_state_is_baked_into_the_script() {
        let html = "<html><head></head></html>";
        assert!(PreviewAudioBridge::new(true)
            .inject("index.html", html)
            .unwrap()
            .contains("let outputVolume = true ? 0 : 1;"));
        assert!(PreviewAudioBridge::new(false)
            .inject("index.html", html)
            .unwrap()
            .contains("let outputVolume = false ? 0 : 1;"));
    }

    #[test]
    fn set_muted_reports_changes() {
        let bridge = PreviewAudioBridge::new(false);
        assert!(bridge.set_muted(true));
        assert!(!bridge.set_muted(true));
        assert!(bridge.muted());
    }
}
